//! Two separately bound review responses. Raw outputs are never stitched into
//! one FRESH_MODEL receipt. Mechanical agreement is not semantic truth.
use crate::common::{a, canonical_hash as hash, error, s, text_sha, Result};
use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet};
pub use crate::semantic_review_v3::{DIMENSIONS, STRUCTURE_FIELDS};
pub const VERSION: &str = "lightog-semantic-review/0.4";
const INPUT: [&str;7] = ["contract_version","candidates","prepared","trusted_context","receipts","context_evidence_ids","max_context_utf16"];
fn need(ok:bool,code:&str)->Result<()>{if ok{Ok(())}else{Err(error(code,code))}}
fn shape(v:&Value,keys:&[&str])->Result<()>{let m=v.as_object().ok_or_else(||error("SPLIT_REVIEW_SHAPE_INVALID","SPLIT_REVIEW_SHAPE_INVALID"))?;need(m.len()==keys.len()&&keys.iter().all(|k|m.contains_key(*k)),"SPLIT_REVIEW_SHAPE_INVALID")}
fn ids(v:&Value,nonempty:bool)->Result<BTreeSet<String>>{let rows=v.as_array().ok_or_else(||error("SPLIT_REVIEW_EVIDENCE_INVALID","SPLIT_REVIEW_EVIDENCE_INVALID"))?;let mut set=BTreeSet::new();need(rows.len()<=10000&&(!nonempty||!rows.is_empty()),"SPLIT_REVIEW_EVIDENCE_INVALID")?;for id in rows{need(id.as_str().is_some_and(|x|!x.is_empty())&&set.insert(s(id).to_owned()),"SPLIT_REVIEW_EVIDENCE_INVALID")?;}Ok(set)}
fn seal(mut value:Value,prefix:&str)->Value{let digest=hash(&value);value["batch_sha256"]=json!(digest);value["batch_id"]=json!(format!("{prefix}{}",&digest[..24]));value}
fn common_input(p:&Value)->Value{let mut v=json!({});for k in INPUT{v[k]=p[k].clone();}v}
fn judgment_schema(decisions:Value)->Value{json!({"type":"object","additionalProperties":false,"required":["decision","reason","evidence_ids"],"properties":{"decision":{"type":"string","enum":decisions},"reason":{"type":"string","minLength":1,"maxLength":4000},"evidence_ids":{"type":"array","uniqueItems":true,"maxItems":128,"items":{"type":"string"}}},"allOf":[{"if":{"properties":{"decision":{"enum":["SUPPORTED","CONSISTENT","NOT_APPLICABLE"]}},"required":["decision"]},"then":{"properties":{"evidence_ids":{"minItems":1}}}}]})}
fn readback_schema(narrative:bool)->Value{let digest=json!({"type":"string","pattern":"^[a-f0-9]{64}$"});let fields:serde_json::Map<_,_>=STRUCTURE_FIELDS.iter().map(|k|((*k).to_owned(),digest.clone())).collect();let mut properties=json!({"structured_candidate_sha256":digest,"structure_field_sha256":{"type":"object","additionalProperties":false,"required":STRUCTURE_FIELDS,"properties":fields}});let mut required=vec!["structured_candidate_sha256","structure_field_sha256"];if narrative{required.push("description_sha256");properties["description_sha256"]=digest;}json!({"type":"object","additionalProperties":false,"required":required,"properties":properties})}
pub fn structure_output_schema()->Value{let dims:serde_json::Map<_,_>=DIMENSIONS.iter().map(|k|((*k).to_owned(),judgment_schema(if *k=="units"{json!(["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN","NOT_APPLICABLE"])}else{json!(["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"])}))).collect();json!({"type":"object","additionalProperties":false,"required":["reviews"],"properties":{"reviews":{"type":"array","maxItems":64,"items":{"type":"object","additionalProperties":false,"required":["candidate_id","decision","dimensions","readback"],"properties":{"candidate_id":{"type":"string"},"decision":{"enum":["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"]},"dimensions":{"type":"object","additionalProperties":false,"required":DIMENSIONS,"properties":dims},"readback":readback_schema(false)}}}}})}
pub fn narrative_output_schema()->Value{let support=judgment_schema(json!(["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"]));json!({"type":"object","additionalProperties":false,"required":["reviews"],"properties":{"reviews":{"type":"array","maxItems":64,"items":{"type":"object","additionalProperties":false,"required":["candidate_id","decision","readback","description_support","condition_exception_fidelity","structure_description_consistency"],"properties":{"candidate_id":{"type":"string"},"decision":{"enum":["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"]},"readback":readback_schema(true),"description_support":support,"condition_exception_fidelity":support,"structure_description_consistency":judgment_schema(json!(["CONSISTENT","CONFLICT","PARTIAL","UNKNOWN"]))}}}}})}
fn role_prepared(base:&Value,narrative:bool)->Value{
 let phase=if narrative{"NARRATIVE"}else{"STRUCTURE"};let schema=if narrative{narrative_output_schema()}else{structure_output_schema()};
 let mut views=vec![];let mut bindings=vec![];
 for row in a(&base["review_view"]){let mut readback=row["readback_expectation"].clone();if !narrative{readback.as_object_mut().unwrap().remove("description_sha256");}let mut view=json!({"candidate_id":row["candidate_id"],"structural_atom":row["structural_atom"],"evidence_roles":row["evidence_roles"],"readback_expectation":readback});if narrative{view["narrative_to_check"]=row["narrative_to_check"].clone();}let mut binding=a(&base["manifest"]["candidates"]).iter().find(|b|b["candidate_id"]==row["candidate_id"]).unwrap().clone();binding["readback_expectation"]=readback;views.push(view);bindings.push(binding);}
 let mut manifest=json!({"contract_version":VERSION,"review_phase":phase,"snapshot_sha256":base["manifest"]["snapshot_sha256"],"prepared_payload_sha256":base["manifest"]["prepared_payload_sha256"],"trusted_context_sha256":base["manifest"]["trusted_context_sha256"],"candidates":bindings,"review_menu_sha256":base["manifest"]["review_menu_sha256"],"review_view_sha256":hash(&json!(views)),"review_output_schema_sha256":hash(&schema),"max_context_utf16":base["manifest"]["max_context_utf16"],"context_utf16":base["manifest"]["context_utf16"],"support_selection_version":base["manifest"]["support_selection_version"],"rubric_version":"independent-structure-narrative/1","structure_fields":STRUCTURE_FIELDS,"positive_evidence_policy":"OWN_FACT_SUPPORT_ONLY_ANCHOR_AND_CONTEXT_NOT_POSITIVE","entity_label_policy":"POSITION_LABEL_NOT_PREDICATE_AUTHORITY","projection_policy":if narrative{"STRUCTURE_AND_UNTRUSTED_TOP_DESCRIPTION_NO_OTHER_REVIEW"}else{"STRUCTURE_ONLY_DROP_TOP_DESCRIPTION_KEYWORDS_KEEP_NESTED_FIELDS"}});
 if let Some(v)=base["manifest"].get("proposal_contract_version"){manifest["proposal_contract_version"]=v.clone();}if !narrative{manifest["dimensions"]=json!(DIMENSIONS);manifest["not_applicable_allowed_dimensions"]=json!(["units"]);}else{manifest["additional_checks"]=json!(["description_support","condition_exception_fidelity","structure_description_consistency"]);}
 json!({"contract_version":VERSION,"review_phase":phase,"manifest":seal(manifest,if narrative{"sr4n_"}else{"sr4s_"}),"review_view":views,"review_menu":base["review_menu"],"review_output_schema":schema,"model_called":false,"publication_performed":false,"semantic_support_certified":false})
}
pub fn prepare(p:&Value)->Result<Value>{need(p["contract_version"]==VERSION,"SPLIT_REVIEW_VERSION_UNSUPPORTED")?;let mut legacy=common_input(p);legacy["contract_version"]=json!(crate::semantic_review_v3::VERSION);let base=crate::semantic_review_v3::prepare(&legacy)?;let structure=role_prepared(&base,false);let narrative=role_prepared(&base,true);let mut manifest=json!({"contract_version":VERSION,"snapshot_sha256":base["manifest"]["snapshot_sha256"],"prepared_payload_sha256":base["manifest"]["prepared_payload_sha256"],"trusted_context_sha256":base["manifest"]["trusted_context_sha256"],"candidate_bindings":a(&base["manifest"]["candidates"]).iter().map(|c|json!({"candidate_id":c["candidate_id"],"candidate_sha256":c["candidate_sha256"],"proposal_receipt_sha256":c["proposal_receipt_sha256"]})).collect::<Vec<_>>(),"structure_manifest_sha256":hash(&structure["manifest"]),"narrative_manifest_sha256":hash(&narrative["manifest"]),"support_selection_version":base["manifest"]["support_selection_version"],"independence_policy":"TWO_DISTINCT_REQUEST_IDS_NOT_PROPOSAL_NO_CROSS_REVIEW_INPUT","combination_policy":"STRUCTURE_SUPPORTED_AND_NARRATIVE_SUPPORTED_AND_CONDITION_EXCEPTION_SUPPORTED_AND_CONSISTENT"});if let Some(v)=base["manifest"].get("proposal_contract_version"){manifest["proposal_contract_version"]=v.clone();}Ok(json!({"contract_version":VERSION,"manifest":seal(manifest,"sr4_"),"structure":structure,"narrative":narrative,"model_called":false,"publication_performed":false,"semantic_support_certified":false}))}
struct Side{parsed:Value,receipt:Value,request_id:String,proposal_ids:BTreeSet<String>,decisions:BTreeMap<String,(bool,Vec<String>)>}
fn enum_value(v:&Value,values:&[&str])->Result<()>{need(values.contains(&s(v)),"SPLIT_REVIEW_OUTPUT_INVALID")}
fn judgment(name:&str,v:&Value,positive:&str,allowed:&[&str],menu:&BTreeSet<String>,support:&BTreeSet<String>,reasons:&mut Vec<String>)->Result<()>{shape(v,&["decision","reason","evidence_ids"])?;enum_value(&v["decision"],allowed)?;let reason=v["reason"].as_str().ok_or_else(||error("SPLIT_REVIEW_REASON_INVALID","SPLIT_REVIEW_REASON_INVALID"))?;need(!reason.trim().is_empty()&&reason.encode_utf16().count()<=4000,"SPLIT_REVIEW_REASON_INVALID")?;let cited=ids(&v["evidence_ids"],false)?;need(cited.is_subset(menu),"SPLIT_REVIEW_OUTPUT_EVIDENCE_UNKNOWN")?;if v["decision"]==positive||v["decision"]=="NOT_APPLICABLE"{if cited.is_empty(){reasons.push(format!("NO_FACT_SUPPORT:{name}"));}else if !cited.is_subset(support){reasons.push(format!("NEEDS_SUPPORT_EXPANSION:{name}"));}}else{reasons.push(format!("CHECK_NOT_SUPPORTED:{name}"));}Ok(())}
fn side(p:&Value,checked:&Value,narrative:bool)->Result<Side>{
 let payload=&p[if narrative{"narrative_review"}else{"structure_review"}];shape(payload,&["manifest","raw_output","review_provenance"])?;let role=&checked[if narrative{"narrative"}else{"structure"}];need(payload["manifest"]==role["manifest"],"SPLIT_REVIEW_MANIFEST_MISMATCH")?;let raw=payload["raw_output"].as_str().ok_or_else(||error("SPLIT_REVIEW_RAW_OUTPUT_REQUIRED","SPLIT_REVIEW_RAW_OUTPUT_REQUIRED"))?;let parsed_receipt=crate::model_json_boundary::parse(raw)?;let parsed=&parsed_receipt["parsed"];shape(parsed,&["reviews"])?;
 let provenance=&payload["review_provenance"];shape(provenance,&["origin","review_request_id","proposal_request_ids","review_output_sha256","raw_output_sha256","model","config_revision"])?;need(["FRESH_MODEL","ARCHIVED_MODEL","SYNTHETIC"].contains(&s(&provenance["origin"]))&&provenance["review_request_id"].as_str().is_some_and(|x|!x.is_empty())&&provenance["model"].as_str().is_some_and(|x|!x.is_empty())&&provenance["config_revision"].as_u64().is_some_and(|n|n>0),"SPLIT_REVIEW_PROVENANCE_INVALID")?;need(provenance["review_output_sha256"]==hash(parsed)&&provenance["raw_output_sha256"]==text_sha(raw),"SPLIT_REVIEW_OUTPUT_BINDING_MISMATCH")?;let proposal_ids=ids(&provenance["proposal_request_ids"],true)?;let request_id=s(&provenance["review_request_id"]).to_owned();need(!proposal_ids.contains(&request_id),"SPLIT_REVIEW_NOT_INDEPENDENT")?;
 let rows=parsed["reviews"].as_array().ok_or_else(||error("SPLIT_REVIEW_OUTPUT_INVALID","SPLIT_REVIEW_OUTPUT_INVALID"))?;need(rows.len()==a(&p["candidates"]).len(),"SPLIT_REVIEW_CANDIDATE_COVERAGE")?;let menu=ids(&json!(a(&role["review_menu"]).iter().map(|f|f["evidence_id"].clone()).collect::<Vec<_>>()),false)?;let mut decisions=BTreeMap::new();let mut annotated=vec![];
 for row in rows{shape(row,if narrative{&["candidate_id","decision","readback","description_support","condition_exception_fidelity","structure_description_consistency"]}else{&["candidate_id","decision","dimensions","readback"]})?;let id=s(&row["candidate_id"]);let binding=a(&role["manifest"]["candidates"]).iter().find(|b|b["candidate_id"]==id).ok_or_else(||error("SPLIT_REVIEW_CANDIDATE_COVERAGE","SPLIT_REVIEW_CANDIDATE_COVERAGE"))?;need(!decisions.contains_key(id),"SPLIT_REVIEW_CANDIDATE_COVERAGE")?;enum_value(&row["decision"],&["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"])?;need(row["readback"]==binding["readback_expectation"],"SPLIT_REVIEW_READBACK_MISMATCH")?;let support=ids(&binding["fact_support_evidence_ids"],true)?;let mut reasons=vec![];if row["decision"]!="SUPPORTED"{reasons.push("TOP_LEVEL_NOT_SUPPORTED".to_owned());}
  if narrative{for key in ["description_support","condition_exception_fidelity"]{judgment(key,&row[key],"SUPPORTED",&["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"],&menu,&support,&mut reasons)?;}judgment("structure_description_consistency",&row["structure_description_consistency"],"CONSISTENT",&["CONSISTENT","CONFLICT","PARTIAL","UNKNOWN"],&menu,&support,&mut reasons)?;}else{shape(&row["dimensions"],&DIMENSIONS)?;let candidate=a(&p["candidates"]).iter().find(|c|c["candidate_id"]==id).unwrap();for dim in DIMENSIONS{let allowed=if dim=="units"{vec!["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN","NOT_APPLICABLE"]}else{vec!["SUPPORTED","PARTIAL","UNSUPPORTED","UNKNOWN"]};judgment(dim,&row["dimensions"][dim],"SUPPORTED",&allowed,&menu,&support,&mut reasons)?;if row["dimensions"][dim]["decision"]=="NOT_APPLICABLE"&&(!candidate["qualifiers"]["unit"].is_null()||!candidate["object"]["typed_value"]["unit"].is_null()||!candidate["object"]["typed_value"]["units"].is_null()){reasons.push("NOT_APPLICABLE_CONFLICTS_WITH_DECLARED_UNIT".to_owned());}}}
  let accepted=reasons.is_empty();decisions.insert(id.to_owned(),(accepted,reasons.clone()));annotated.push(json!({"candidate_id":id,"candidate_sha256":binding["candidate_sha256"],"gate_status":if accepted{"ROLE_SUPPORTED"}else{"ROLE_HELD"},"gate_reasons":reasons}));
 }
 let receipt=json!({"contract_version":VERSION,"review_phase":role["review_phase"],"manifest":role["manifest"],"raw_output":raw,"raw_output_sha256":text_sha(raw),"review_output":parsed,"review_output_sha256":hash(parsed),"review_provenance":provenance,"parse_receipt":parsed_receipt["receipt"],"candidate_results":annotated,"semantic_support_certified":false,"publication_performed":false});Ok(Side{parsed:parsed.clone(),receipt,request_id,proposal_ids,decisions})
}
fn apply(p:&Value)->Result<Value>{let checked=prepare(p)?;need(p["manifest"]==checked["manifest"],"SPLIT_REVIEW_MANIFEST_MISMATCH")?;let structure=side(p,&checked,false)?;let narrative=side(p,&checked,true)?;need(structure.request_id!=narrative.request_id&&structure.proposal_ids==narrative.proposal_ids,"SPLIT_REVIEW_NOT_INDEPENDENT")?;let mut eligible=vec![];let mut quarantined=vec![];for c in a(&p["candidates"]){let id=s(&c["candidate_id"]);let (sa,sr)=&structure.decisions[id];let (na,nr)=&narrative.decisions[id];if *sa&&*na{eligible.push(c.clone());}else{let reasons:Vec<_>=sr.iter().map(|r|format!("STRUCTURE:{r}")).chain(nr.iter().map(|r|format!("NARRATIVE:{r}"))).collect();quarantined.push(json!({"candidate_id":id,"candidate_sha256":hash(c),"reasons":reasons}));}}
 let graph=crate::knowledge_build::build(&json!({"candidates":eligible,"snapshot":p["prepared"]["payload"]["snapshot"],"trusted_context":p["trusted_context"]}))?;let receipt=json!({"contract_version":VERSION,"manifest":checked["manifest"],"structure_review":structure.receipt,"narrative_review":narrative.receipt,"eligible_candidate_ids":eligible.iter().map(|c|c["candidate_id"].clone()).collect::<Vec<_>>(),"candidate_archive_sha256":hash(&graph["graph"]["candidate_archive"]),"review_origin":"TWO_SEPARATELY_BOUND_RESPONSES_NOT_ONE_MODEL_OUTPUT","semantic_support_certified":false,"publication_performed":false});Ok(json!({"contract_version":VERSION,"manifest":checked["manifest"],"eligible_candidates":eligible,"quarantined":quarantined,"all_proposal_candidates":p["candidates"],"review_receipt":receipt,"reviewed_build":graph,"review_origin":"TWO_SEPARATELY_BOUND_RESPONSES_NOT_ONE_MODEL_OUTPUT","semantic_support_certified":false,"publication_performed":false}))
}
pub fn execute(op:&str,p:&Value)->Result<Value>{need(serde_json::to_vec(p).map_err(|_|error("SPLIT_REVIEW_SHAPE_INVALID","SPLIT_REVIEW_SHAPE_INVALID"))?.len()<=8*1024*1024,"SPLIT_REVIEW_RESOURCE_LIMIT")?;let extra=match op{"prepare"|"prepare_structure"|"prepare_narrative"=>vec![],"validate_structure"=>vec!["manifest","structure_review"],"apply"=>vec!["manifest","structure_review","narrative_review"],_=>return Err(error("SPLIT_REVIEW_OPERATION_UNKNOWN","SPLIT_REVIEW_OPERATION_UNKNOWN"))};let keys:Vec<_>=INPUT.into_iter().chain(extra).collect();shape(p,&keys)?;match op{"prepare"=>prepare(p),"prepare_structure"=>Ok(prepare(p)?["structure"].clone()),"prepare_narrative"=>Ok(prepare(p)?["narrative"].clone()),"validate_structure"=>{let checked=prepare(p)?;need(p["manifest"]==checked["manifest"],"SPLIT_REVIEW_MANIFEST_MISMATCH")?;let result=side(p,&checked,false)?;Ok(json!({"contract_version":VERSION,"review_phase":"STRUCTURE","structure_supported_candidate_ids":result.decisions.iter().filter(|(_,v)|v.0).map(|(k,_)|k).collect::<Vec<_>>(),"structure_receipt":result.receipt,"full_output_sha256":hash(&result.parsed),"semantic_support_certified":false,"publication_performed":false}))},_=>apply(p)}}
